-- PHLPost's published ZIP Code Locator snapshot, captured 2026-09-27.
-- It contains incomplete locality coverage and one populated row with a non-ZIP value;
-- the malformed row is omitted and any locality without rows remains unknown.
CREATE TABLE IF NOT EXISTS public.phlpost_postal_codes (
  region_name text NOT NULL,
  province_name text NOT NULL,
  locality_name text NOT NULL,
  postal_code text NOT NULL CHECK (postal_code ~ '^[0-9]{4}$'),
  region_key text NOT NULL,
  province_key text NOT NULL,
  locality_key text NOT NULL,
  captured_on date NOT NULL DEFAULT DATE '2026-09-27',
  PRIMARY KEY (province_key, locality_key, postal_code)
);

CREATE INDEX IF NOT EXISTS idx_phlpost_postal_locality
  ON public.phlpost_postal_codes (province_key, locality_key);

COMMENT ON TABLE public.phlpost_postal_codes IS
  'PHLPost ZIP Code Locator snapshot from 2026-09-27; incomplete locality coverage and malformed source rows are treated as unknown. Source: https://phlpost.gov.ph/zip-code-locator/';

ALTER TABLE public.phlpost_postal_codes ENABLE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE public.phlpost_postal_codes FROM anon, authenticated;

